 instances(new THREE.CylinderGeometry(.23,.23,.008,24),ink,pose(.446)).name='Ouroboros eye pupil';
 const nose=pixel(341,39);instances(new THREE.SphereGeometry(.09,12,8),ink,[0,1,2,3].map(f=>({position:new THREE.Vector3(nose.x,f*spacing+.431,nose.z),scale:new THREE.Vector3(1,.12,1)}))).name='Ouroboros nostril';
