 const rockTextureCanvas=document.createElement('canvas');rockTextureCanvas.width=rockTextureCanvas.height=256;const rockContext=rockTextureCanvas.getContext('2d');rockContext.fillStyle='#777a78';rockContext.fillRect(0,0,256,256);for(let i=0;i<2400;i++){const shade=50+(i*37%95);rockContext.strokeStyle='rgb('+shade+','+shade+','+shade+')';rockContext.lineWidth=.8+(i%3)*.4;const x=(i*79)%256,y=(i*113)%256;rockContext.beginPath();rockContext.moveTo(x,y);rockContext.lineTo(x+(i%9)-4,y+3+(i%7));rockContext.stroke()}
