 const c=renderer.domElement;c.addEventListener('pointerdown',e=>{pointer.down=true;pointer.lastX=e.clientX;pointer.lastY=e.clientY;pointer.moved=0;c.setPointerCapture(e.pointerId);stopTour()});c.addEventListener('pointermove',e=>{if(!pointer.down)return;const dx=e.clientX-pointer.lastX,dy=e.clientY-pointer.lastY;pointer.lastX=e.clientX;pointer.lastY=e.clientY;pointer.moved+=Math.abs(dx)+Math.abs(dy);if(inside){player.yaw-=dx*.004;player.pitch=THREE.MathUtils.clamp(player.pitch-dy*.003,-.8,.75)}else{exteriorAngle-=dx*.006;exteriorHeight=THREE.MathUtils.clamp(exteriorHeight+dy*.2,65,360)}});c.addEventListener('pointerup',e=>{pointer.down=false;if(pointer.moved<8&&!transition&&!returnLift&&!modalActive())pickSceneAt(e.clientX,e.clientY)});c.addEventListener('pointercancel',()=>pointer.down=false);c.addEventListener('wheel',e=>{if(inside)return;exteriorRadius=THREE.MathUtils.clamp(exteriorRadius+e.deltaY*.08,160,760)},{passive:true});
