function drawSharedMap(){const c=$('map'),ctx=c.getContext('2d'),s=.33,cx=130,cz=181;ctx.clearRect(0,0,260,260);ctx.strokeStyle='#d2bd885f';ctx.lineWidth=2;const path=points=>{ctx.beginPath();points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](cx+p[0]*s,cz+p[1]*s));ctx.stroke()};path([[0,58],[0,94],[-97.7,110],[-97.7,103.8]]);path([[0,94],[82.9,108]]);path([[0,94],[65,75],[sharedCity.A.x,sharedCity.A.radius+10]]);path([[-97.7,110],[-86,45],[-84,-9],[-138,-32]]);path([[-84,-9],[-84,-110],[0,-185],[0,-195]]);path([[-138,-32],[-138,-150],[0,-185]]);const circle=(x,z,r,color,label)=>{ctx.strokeStyle=color;ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(cx+x*s,cz+z*s,r*s,0,Math.PI*2);ctx.stroke();ctx.font='10px Tahoma';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(label,cx+x*s,cz+(z+r+17)*s)};circle(0,0,58,'#d3c5a1',tx('زرتشت','Zarathustra'));circle(sharedCity.A.x,0,47,'#89b9a6',tx('کوه','Mountain'));circle(-96,100,18,'#b4c39c',tx('سقراط','Socrates'));circle(118,108,31,'#ddafad',tx('هنرمندان','Artists'));circle(-138,-79,32,'#d9bf8f',tx('اشیا','Objects'));circle(0,-330,156,'#a3cbaa',tx('پارک ایده‌ها','Ideas Park'));ctx.strokeStyle='#89b9a6';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<=160;i++){const q=sharedCity.pointAt(i/160*sharedCity.MAX);ctx[i?'lineTo':'moveTo'](cx+q.x*s,cz+q.z*s)}ctx.stroke();ctx.fillStyle='#f1c36d';ctx.beginPath();ctx.arc(cx+player.x*s,cz+player.z*s,3.8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#efca85';ctx.beginPath();ctx.moveTo(cx+player.x*s,cz+player.z*s);ctx.lineTo(cx+(player.x-Math.sin(player.yaw)*12)*s,cz+(player.z-Math.cos(player.yaw)*12)*s);ctx.stroke()}
function drawMap(){if($('map-panel').hidden)return;if(visitMode!=='gallery'){drawSharedMap();return}const c=$('map'),ctx=c.getContext('2d'),center=130,s=118/outer;ctx.clearRect(0,0,260,260);ctx.strokeStyle='#5f6a69';ctx.lineWidth=1;ctx.fillStyle='#2f3e41';ctx.beginPath();ctx.arc(center,center,outer*s,0,Math.PI*2);ctx.arc(center,center,inner*s,0,Math.PI*2,true);ctx.fill('evenodd');ctx.stroke();ctx.strokeStyle='#d4af7040';ctx.setLineDash([3,5]);ctx.beginPath();ctx.arc(center,center,routeRadius*s,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);exhibitRoots.filter(r=>r.userData.floor===currentFloor).forEach(r=>{ctx.beginPath();ctx.fillStyle=floors[currentFloor].color;ctx.arc(center+r.position.x*s,center+r.position.z*s,4,0,Math.PI*2);ctx.fill()});ctx.fillStyle='#efca85';ctx.beginPath();ctx.arc(center+player.x*s,center+player.z*s,4.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#efca85';ctx.beginPath();ctx.moveTo(center+player.x*s,center+player.z*s);ctx.lineTo(center+(player.x-Math.sin(player.yaw)*3)*s,center+(player.z-Math.cos(player.yaw)*3)*s);ctx.stroke();ctx.fillStyle='#b0b6ae';ctx.font='11px Tahoma';ctx.textAlign='center';ctx.fillStyle='#3c3330';ctx.beginPath();ctx.arc(center,center,21*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6a555';ctx.beginPath();ctx.arc(center,center,6*s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eec981';ctx.font='10px Tahoma';ctx.fillText(tx('زایش','Birth'),130,151)}
